<script setup lang="ts">
/**
 * A single show-or-hide section with one trigger (`design/components/collapsible.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/collapsible.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, useId, useTemplateRef } from 'vue'

import * as zag from '@zag-js/collapsible'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { Icon, agentMember, useDirection } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/collapsible.module.css'

export interface CollapsibleProps {
  /**
   * Closed by default, because a disclosure that starts open hides nothing.
   */
  defaultOpen?: boolean
  /**
   * The trigger's text, naming what is disclosed in the product's words.
   */
  label: string
  /**
   * Controlled state, paired with `onOpenChange` as in Radix.
   */
  open?: boolean
}

defineOptions({ name: 'Collapsible', inheritAttrs: false })

const props = withDefaults(defineProps<CollapsibleProps>(), { defaultOpen: false, open: undefined })
const emit = defineEmits<{ openChange: [open: boolean] }>()
defineSlots<{ default: (props: Record<string, never>) => unknown }>()
const uid = useId()
const trigger = useTemplateRef<HTMLElement>('trigger')
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    open: props.open,
    defaultOpen: props.defaultOpen,
    onOpenChange: (details) => {
      emit('openChange', details.open)
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Collapsible',
    element: () => trigger.value,
    state: () => ({ open: api.value.open }),
    actions: {
      open: () => api.value.open || api.value.setOpen(true),
      close: () => api.value.open && api.value.setOpen(false),
    },
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <div v-bind="api.getRootProps()" :class="styles.root" data-member="collapsible">
    <!-- trigger -->
    <button ref="trigger" v-bind="api.getTriggerProps()" :class="styles.trigger">
      <span :class="styles.label">
        {{ label }}
      </span>
      <span :class="styles.chevron">
        <Icon name="down" size="sm" />
      </span>
    </button>
    <!-- content -->
    <div
      v-bind="api.getContentProps()"
      :class="styles.content"
      :style="{
        '--radix-collapsible-content-height': Object(api.getContentProps().style)['--height'],
      }"
    >
      <div :class="styles.inner">
        <slot />
      </div>
    </div>
  </div>
</template>
